20	// real sum (rounded to float64 once) and their single-increment range;
21	// Rate is Sum divided by the window width in seconds.
22	type RateWindow struct {
23		Start time.Time
24		Count int64
25		Sum   float64
26		Min   float64
27		Max   float64
28		Rate  float64
29	}
30	
31	// Counter derives per-window rates from a monotonically non-decreasing
32	// cumulative counter that may reset. Samples are cumulative readings in
33	// non-decreasing time order, like a Roller's, but their values must be
34	// finite and non-negative. The first sample only establishes the
35	// baseline; each later sample produces one increment relative to the
36	// previous reading:
37	//
38	//   - a reading at least as large as the previous one increments by the
39	//     one float64 subtraction current-previous;
40	//   - a reading smaller than the previous one is a reset and increments by
41	//     the reading itself.
42	//
43	// Increments are always non-negative; a zero increment is filed like any
44	// other. Samples at the same instant are taken in arrival order, and each
45	// increment belongs to the window of the later sample, so same-instant
46	// samples can yield zero or reset increments.
47	//
48	// The zero value is not usable; build one with NewCounter. All methods
49	// are safe to call concurrently from multiple goroutines, and every read
50	// observes an internally consistent snapshot: a batch is visible to other
51	// callers either in full or not at all.
52	type Counter struct {
53		// mu guards buckets, bstats, back, latest, prev, and has. window is
54		// fixed at construction and read without the lock. The window storage
55		// follows the same buckets-plus-backfill scheme as Roller: increments
56		// arrive in non-decreasing time order, so they append in amortized
57		// constant time and reads stay sorted.
58		mu      sync.RWMutex
59		window  time.Duration
60		buckets []Window
61		bstats  []stats
62		back    map[time.Time]backWindow
63		latest  time.Time
64		prev    float64
65		has     bool
66	}
67	
68	// NewCounter builds a counter with the given window size. It panics with
69	// "rollup: bad window" if window is not positive.
70	func NewCounter(window time.Duration) *Counter {
71		if window <= 0 {
72			panic("rollup: bad window")
73		}
74		return &Counter{window: window}
75	}
76	
77	// startOf returns the start of the window containing at, aligned to an
78	// integer multiple of the window size since the Unix epoch.
79	func (c *Counter) startOf(at time.Time) time.Time {
80		return alignStart(at, c.window.Nanoseconds())
81	}
82	
83	// Add files one cumulative counter reading. A non-finite value (NaN or an
84	// infinity) is rejected with ErrNonFinite, a negative value with
85	// ErrNegativeCounter, and a reading earlier than the most recent accepted
86	// reading with ErrOutOfOrder. In every rejection case the counter,
87	// including its baseline and most-recent marker, is left unchanged; a
88	// reading at the same instant as the marker is accepted and produces its
89	// increment in arrival order.
90	//
91	// Concurrent Adds are serialized: each takes effect in the order it
92	// acquires the counter, and the checks are measured against the readings
93	// accepted before it in that order.
94	func (c *Counter) Add(at time.Time, value float64) error {
95		if math.IsNaN(value) || math.IsInf(value, 0) {
96			return ErrNonFinite
97		}
98		if value < 0 {
99			return ErrNegativeCounter
100		}
101		c.mu.Lock()
102		defer c.mu.Unlock()
103		if c.has && at.Before(c.latest) {
104			return ErrOutOfOrder
105		}
106		c.applyLocked(at, value)
107		return nil
108	}
109	
110	// AddBatch files a batch of cumulative readings as one atomic unit: either
111	// every reading takes effect or none does. The readings may arrive in any
112	// order and are not checked against each other; several readings at the
113	// same instant each produce an increment in arrival order. The first
114	// reading of the whole stream only establishes the baseline, and every
115	// later reading in the batch is diffed against the preceding one exactly
116	// as Add would diff it.
117	//
118	// A batch holding any non-finite value is rejected with ErrNonFinite, one
119	// holding any negative value with ErrNegativeCounter, and one whose
120	// readings predate the most recent reading already accepted with
121	// ErrOutOfOrder. Any rejection leaves the counter, its baseline, and its
122	// most-recent marker unchanged. Otherwise the marker advances to the
123	// later of its previous value and the newest reading in the batch. A nil
124	// or empty batch is accepted, changes nothing, and does not advance the
125	// marker.
126	//
127	// The batch is atomic with respect to every other call on the counter:
128	// concurrent adds, rate reads, and cursor creation observe the counter
129	// wholly before or wholly after the batch.
130	func (c *Counter) AddBatch(samples []Sample) error {
131		if len(samples) == 0 {
132			return nil
133		}
134		// Value checks scan the whole batch first, so one bad reading rejects
135		// the unit even when a stale reading sits earlier in the slice.
136		// Nothing is filed until the batch is fully validated.
137		for _, s := range samples {
138			if math.IsNaN(s.Value) || math.IsInf(s.Value, 0) {
139				return ErrNonFinite
140			}
141		}
142		for _, s := range samples {
143			if s.Value < 0 {
144				return ErrNegativeCounter
145			}
146		}
147		c.mu.Lock()
148		defer c.mu.Unlock()
149		latest := samples[0].At
150		for _, s := range samples {
151			if c.has && s.At.Before(c.latest) {
152				return ErrOutOfOrder
153			}
154			if s.At.After(latest) {
155				latest = s.At
156			}
157		}
158		if c.has && c.latest.After(latest) {
159			latest = c.latest
160		}
161		for _, s := range samples {
162			c.applyLocked(s.At, s.Value)
163		}
164		c.latest = latest
165		return nil
166	}
167	
168	// applyLocked folds one validated reading into the counter: the first
169	// sets the baseline, later ones file the increment against the previous
170	// reading. The caller must hold mu and must already have cleared the
171	// non-finite, negative, and out-of-order checks.
172	func (c *Counter) applyLocked(at time.Time, value float64) {
173		if !c.has {
174			c.has = true
175			c.prev = value
176			c.latest = at
177			return
178		}
179		delta := value - c.prev
180		if value < c.prev {
181			// The counter reset: the reading since the reset is the reading
182			// itself. Equal readings subtract to a positive zero and file a
183			// zero increment; a reset to zero files one too.
184			delta = value
185		}
186		if delta == 0 {
187			// A zero increment is always a positive zero, even when the
188			// reset reading arrived as a negative zero.
189			delta = 0
190		}
191		c.fileDeltaLocked(at, delta)
192		c.prev = value
193		c.latest = at
194	}
195	
196	// fileDeltaLocked folds one non-negative increment into its window. The
197	// caller must hold mu.
198	func (c *Counter) fileDeltaLocked(at time.Time, delta float64) {
199		start := c.startOf(at)
200		n := len(c.buckets)
201		switch {
202		case n == 0:
203			c.buckets = append(c.buckets, newBucket(start, delta))
204			c.bstats = append(c.bstats, seedStats(delta))
205		case !start.Before(c.buckets[n-1].Start):
206			// The common case: the increment lands in the newest window or
207			// just past it, so the sorted order is maintained for free.
208			if c.buckets[n-1].Start.Equal(start) {
209				addTo(&c.buckets[n-1], &c.bstats[n-1], delta)
210			} else {
211				c.buckets = append(c.buckets, newBucket(start, delta))
212				c.bstats = append(c.bstats, seedStats(delta))
213			}
214		default:
215			// An older window can only receive an increment when the batch's
216			// readings are out of time order. A window that already exists is
217			// updated in place; a new one goes into the backfill map.
218			if i, ok := windowIndex(c.buckets, start); ok {
219				addTo(&c.buckets[i], &c.bstats[i], delta)
220			} else if bw, ok := c.back[start]; ok {
221				addTo(&bw.w, &bw.st, delta)
222				c.back[start] = bw
223			} else {
224				if c.back == nil {
225					c.back = make(map[time.Time]backWindow)
226				}
227				c.back[start] = backWindow{w: newBucket(start, delta), st: seedStats(delta)}
228				c.maybeFlushBackLocked()
229			}
230		}
231	}
232	
233	// maybeFlushBackLocked folds the backfilled windows into buckets once
234	// they number at least half as many as buckets, so the sorting and merge
235	// cost amortizes to constant time per backfilled window. The caller must
236	// hold mu.
237	func (c *Counter) maybeFlushBackLocked() {
238		if len(c.back)*2 < len(c.buckets) {
239			return
240		}
241		bw, bs := c.sortedBackLocked()
242		c.buckets, c.bstats = mergeWindows(c.buckets, c.bstats, bw, bs)
243		c.back = nil
244	}
245	
246	// sortedBackLocked returns the backfilled windows in time order. The
247	// caller must hold mu; the returned slices are fresh and aligned and each
248	// stats owns an independent rational.
249	func (c *Counter) sortedBackLocked() ([]Window, []stats) {
250		starts := make([]time.Time, 0, len(c.back))
251		for s := range c.back {
252			starts = append(starts, s)
253		}
254		sort.Slice(starts, func(i, j int) bool {
255			return starts[i].Before(starts[j])
256		})
257		ws := make([]Window, len(starts))
258		ss := make([]stats, len(starts))
259		for i, s := range starts {
260			bw := c.back[s]
261			ws[i] = bw.w
262			ss[i] = cloneStats(bw.st)
263		}
264		return ws, ss
265	}
266	
267	// sortedBackWindowsLocked returns just the backfilled windows in time
268	// order for display reads. The caller must hold mu.
269	func (c *Counter) sortedBackWindowsLocked() []Window {
270		starts := make([]time.Time, 0, len(c.back))
271		for s := range c.back {
272			starts = append(starts, s)
273		}
274		sort.Slice(starts, func(i, j int) bool {
275			return starts[i].Before(starts[j])
276		})
277		ws := make([]Window, len(starts))
278		for i, s := range starts {
279			ws[i] = c.back[s].w
280		}
281		return ws
282	}
283	
284	// windowsLocked returns every window holding at least one increment, in
285	// time order, as a snapshot copy. The caller must hold mu.
286	func (c *Counter) windowsLocked() []Window {
287		if len(c.back) == 0 {
288			out := make([]Window, len(c.buckets))
289			copy(out, c.buckets)
290			return out
291		}
292		back := c.sortedBackWindowsLocked()
293		merged := make([]Window, 0, len(c.buckets)+len(back))
294		i, j := 0, 0
295		for i < len(c.buckets) && j < len(back) {
296			if c.buckets[i].Start.Before(back[j].Start) {
297				merged = append(merged, c.buckets[i])
298				i++
299			} else {
300				merged = append(merged, back[j])
301				j++
302			}
303		}
304		merged = append(merged, c.buckets[i:]...)
305		merged = append(merged, back[j:]...)
306		return merged
307	}
308	
309	// toRateWindows derives RateWindows from a time-ordered window snapshot,
310	// attaching each window's rate and dropping the ones outside the
311	// half-open interval [from, to).
312	func (c *Counter) toRateWindows(ws []Window, from, to time.Time) []RateWindow {
313		out := []RateWindow{}
314		secs := c.window.Seconds()
315		lo := c.startOf(from)
316		for _, w := range ws {
317			if w.Start.Before(lo) {
318				continue
319			}
320			if !w.Start.Before(to) {
321				break
322			}
323			out = append(out, RateWindow{
324				Start: w.Start,
325				Count: w.Count,
326				Sum:   w.Sum,
327				Min:   w.Min,
328				Max:   w.Max,
329				Rate:  w.Sum / secs,
330			})
331		}
332		return out
333	}
334	
335	// Rates returns the windows that both overlap the half-open interval
336	// [from, to) and hold at least one increment, in time order by window
337	// start. Windows are selected by the same epoch-aligned, left-closed rule
338	// a Roller's Range uses: the first window reported is the one containing
339	// from, and a window starting exactly at to is excluded. Every reported
340	// window carries its rate, its increment sum divided by the window width
341	// in seconds as one float64 division. An interval whose end does not come
342	// after its start yields an empty slice, as does one no increment-bearing
343	// window overlaps. The result is a snapshot of one moment: readings filed
344	// after the call do not alter it.
345	func (c *Counter) Rates(from, to time.Time) []RateWindow {
346		c.mu.RLock()
347		ws := c.windowsLocked()
348		c.mu.RUnlock()
349		if !from.Before(to) {
350			return []RateWindow{}
351		}
352		return c.toRateWindows(ws, from, to)
353	}
354	
355	// RateCursor reads rate windows over a fixed range in batches. The
356	// windows are snapshotted when the cursor is created: readings filed
357	// afterwards do not alter what the cursor returns, so batched iteration
358	// over a large range never tears, skips, or repeats a window.
359	//
360	// A RateCursor is safe to advance from multiple goroutines at once; each
361	// batch is handed out exactly once.
362	type RateCursor struct {
363		// mu guards pos. windows is fixed at creation and read without the
364		// lock.
365		mu      sync.Mutex
366		windows []RateWindow
367		pos     int
368	}
369	
370	// RateCursor returns a cursor over the rate windows overlapping the
371	// half-open interval [from, to), selected by the same rule as Rates.
372	func (c *Counter) RateCursor(from, to time.Time) *RateCursor {
373		return &RateCursor{windows: c.Rates(from, to)}
374	}
375	
376	// Next returns the next batch of up to n rate windows, in time order.
377	// Batches are consecutive and non-overlapping: together they cover exactly
378	// the windows in the cursor's range. Once the range is exhausted, Next
379	// returns an empty slice and the cursor does not move. A non-positive n
380	// yields an empty slice and does not advance the cursor.
381	func (c *RateCursor) Next(n int) []RateWindow {
382		c.mu.Lock()
383		defer c.mu.Unlock()
384		rest := len(c.windows) - c.pos
385		if n <= 0 || rest == 0 {
386			return []RateWindow{}
387		}
388		if n > rest {
389			n = rest
390		}
391		out := make([]RateWindow, n)
392		copy(out, c.windows[c.pos:c.pos+n])
393		c.pos += n
394		return out
395	}
