1	// Command rollupctl reads timestamped samples from a file, files them into
2	// fixed windows aligned to the Unix epoch, and prints, one per line, each
3	// window's start, count, sum, minimum, and maximum.
4	//
5	// Usage:
6	//
7	//	rollupctl --file <path> --window <duration> windows
8	//	rollupctl --file <path> --window <duration> --from <ns> --to <ns> range
9	//	rollupctl --file <path> --file <path> --window <duration> merge
10	//	rollupctl --file <path> --window <duration> --from <ns> --to <ns> rates
11	//
12	// The input file holds one sample per line: an integer number of
13	// nanoseconds since the epoch, whitespace, then a floating-point value.
14	// Blank and whitespace-only lines carry no sample. Samples must arrive in
15	// non-decreasing time order. The values given to rates are cumulative
16	// counter readings and must be finite and non-negative.
17	//
18	// The windows subcommand prints every window. The range subcommand prints
19	// only the windows overlapping the half-open interval [--from, --to), both
20	// endpoints given as nanoseconds since the epoch. The merge subcommand
21	// aggregates two files with the same window duration and prints their
22	// windows combined into one listing. The rates subcommand treats the
23	// values as a cumulative counter that may reset and prints, for every
24	// epoch-aligned window overlapping [--from, --to) that holds at least one
25	// increment, its start, increment count, increment sum, minimum, maximum,
26	// and rate (the increment sum divided by the window width in seconds).
27	//
28	// Exit codes: 0 success, 2 bad command-line arguments, 3 an input file
29	// does not exist or is a directory, 4 an input file's contents are
30	// invalid, including a negative counter value, or the two files cannot be
31	// merged.
32	package main
33	
34	import (
35		"bufio"
36		"errors"
37		"fmt"
38		"io"
39		"math"
40		"math/big"
41		"os"
42		"strconv"
43		"strings"
44		"time"
45	
46		"github.com/Hulalalalalalalalalalala/metric-rollup/rollup"
47	)
48	
49	// maxLineBytes is the longest accepted physical input line, excluding the
50	// line terminator.
51	const maxLineBytes = 1024
52	
53	// rangeBatchSize is the number of windows the range subcommand asks the
54	// cursor for at a time, so printing a long interval streams in batches
55	// instead of materializing one listing per window.
56	const rangeBatchSize = 1024
57	
58	func main() {
59		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
60	}
61	
62	// command holds the parsed command line: which subcommand to run and the
63	// flag values it consumes.
64	type command struct {
65		sub            string
66		files          []string
67		window         string
68		from, to       string
69		hasFrom, hasTo bool
70	}
71	
72	// run parses args, reads the input file or files, and writes the window
73	// listing. It returns the process exit code; every diagnostic is a single
74	// line on stderr prefixed with "rollupctl: ".
75	func run(args []string, stdout, stderr io.Writer) int {
76		cmd, ok := parseArgs(args, stderr)
77		if !ok {
78			return 2
79		}
80		d, err := time.ParseDuration(cmd.window)
81		if err != nil {
82			argError(stderr, "invalid --window %q: %v", cmd.window, err)
83			return 2
84		}
85		if d <= 0 {
86			argError(stderr, "--window must be positive, got %s", d)
87			return 2
88		}
89	
90		switch cmd.sub {
91		case "range":
92			from, err := strconv.ParseInt(cmd.from, 10, 64)
93			if err != nil {
94				argError(stderr, "invalid --from %q: %v", cmd.from, err)
95				return 2
96			}
97			to, err := strconv.ParseInt(cmd.to, 10, 64)
98			if err != nil {
99				argError(stderr, "invalid --to %q: %v", cmd.to, err)
100				return 2
101			}
102			return runRange(cmd.files[len(cmd.files)-1], d, from, to, stdout, stderr)
103		case "rates":
104			from, err := strconv.ParseInt(cmd.from, 10, 64)
105			if err != nil {
106				argError(stderr, "invalid --from %q: %v", cmd.from, err)
107				return 2
108			}
109			to, err := strconv.ParseInt(cmd.to, 10, 64)
110			if err != nil {
111				argError(stderr, "invalid --to %q: %v", cmd.to, err)
112				return 2
113			}
114			return runRates(cmd.files[len(cmd.files)-1], d, from, to, stdout, stderr)
115		case "merge":
116			return runMerge(cmd.files[0], cmd.files[1], d, stdout, stderr)
117		default:
118			return runWindows(cmd.files[len(cmd.files)-1], d, stdout, stderr)
119		}
120	}
121	
122	// runWindows prints every window of one file's samples.
123	func runWindows(path string, d time.Duration, stdout, stderr io.Writer) int {
124		roller, code := ingestFile(path, d, stderr)
125		if code != 0 {
126			return code
127		}
128		out := bufio.NewWriter(stdout)
129		writeWindows(out, roller.Windows())
130		return flush(out, stderr)
131	}
132	
133	// runRange prints the windows of one file's samples that overlap the
134	// half-open interval [from, to), advancing through them in cursor batches.
135	// An empty or backwards interval is not an error and prints nothing.
136	func runRange(path string, d time.Duration, from, to int64, stdout, stderr io.Writer) int {
137		roller, code := ingestFile(path, d, stderr)
138		if code != 0 {
139			return code
140		}
141		out := bufio.NewWriter(stdout)
142		cursor := roller.Cursor(time.Unix(0, from).UTC(), time.Unix(0, to).UTC())
143		for {
144			batch := cursor.Next(rangeBatchSize)
145			if len(batch) == 0 {
146				break
147			}
148			writeWindows(out, batch)
149		}
150		return flush(out, stderr)
151	}
152	
153	// runRates treats one file's values as a cumulative counter and prints
154	// the rate windows that overlap the half-open interval [from, to),
155	// advancing through them in cursor batches. An empty or backwards
156	// interval is not an error and prints nothing.
157	func runRates(path string, d time.Duration, from, to int64, stdout, stderr io.Writer) int {
158		counter, code := ingestCounterFile(path, d, stderr)
159		if code != 0 {
160			return code
161		}
162		out := bufio.NewWriter(stdout)
163		cursor := counter.RateCursor(time.Unix(0, from).UTC(), time.Unix(0, to).UTC())
164		for {
165			batch := cursor.Next(rangeBatchSize)
166			if len(batch) == 0 {
167				break
168			}
169			writeRates(out, batch)
170		}
171		return flush(out, stderr)
172	}
173	
174	// writeRates prints one line per rate window: start, count, sum, min, max,
175	// rate.
176	func writeRates(out *bufio.Writer, ws []rollup.RateWindow) {
177		for _, w := range ws {
178			fmt.Fprintf(out, "%s %d %s %s %s %s\n",
179				unixNanoText(w.Start), w.Count,
180				formatFloat(w.Sum), formatFloat(w.Min), formatFloat(w.Max),
181				formatFloat(w.Rate))
182		}
183	}
184	
185	// runMerge aggregates two files with the same window duration and prints
186	// their combined windows. Both files are fully ingested before anything is
187	// printed, so a problem in either one leaves the listing empty.
188	func runMerge(pathA, pathB string, d time.Duration, stdout, stderr io.Writer) int {
189		rollerA, code := ingestFile(pathA, d, stderr)
190		if code != 0 {
191			return code
192		}
193		rollerB, code := ingestFile(pathB, d, stderr)
194		if code != 0 {
195			return code
196		}
197		if err := rollerA.Merge(rollerB); err != nil {
198			writeMergeError(stderr, pathA, pathB, err)
199			return 4
200		}
201		out := bufio.NewWriter(stdout)
202		writeWindows(out, rollerA.Windows())
203		return flush(out, stderr)
204	}
205	
206	// writeWindows prints one line per window: start, count, sum, min, max.
207	func writeWindows(out *bufio.Writer, ws []rollup.Window) {
208		for _, w := range ws {
209			fmt.Fprintf(out, "%s %d %s %s %s\n",
210				unixNanoText(w.Start), w.Count,
211				formatFloat(w.Sum), formatFloat(w.Min), formatFloat(w.Max))
212		}
213	}
214	
215	// flush flushes out and reports a write failure as exit code 1.
216	func flush(out *bufio.Writer, stderr io.Writer) int {
217		if err := out.Flush(); err != nil {
218			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
219			return 1
220		}
221		return 0
222	}
223	
224	// argError writes one command-line usage diagnostic.
225	func argError(stderr io.Writer, format string, a ...any) {
226		fmt.Fprintf(stderr, "rollupctl: "+format+"\n", a...)
227	}
228	
229	// writeMergeError writes the one merge diagnostic: the two file names in
230	// command-line order, separated by a comma and a space, followed by the
231	// reason the merge could not combine them.
232	func writeMergeError(stderr io.Writer, pathA, pathB string, err error) {
233		fmt.Fprintf(stderr, "rollupctl: %s, %s: %v\n", pathA, pathB, err)
234	}
235	
236	// parseArgs extracts the subcommand and the flag values. Flags may stand
237	// on either side of the subcommand, Go-style: --name value, --name=value,
238	// with one or two leading dashes.
239	func parseArgs(args []string, stderr io.Writer) (command, bool) {
240		fail := func(format string, a ...any) (command, bool) {
241			argError(stderr, format, a...)
242			return command{}, false
243		}
244		var cmd command
245		sub := ""
246		flagsEnded := false
247		for i := 0; i < len(args); i++ {
248			a := args[i]
249			if !flagsEnded && a == "--" {
250				flagsEnded = true
251				continue
252			}
253			if flagsEnded || !strings.HasPrefix(a, "-") || a == "-" {
254				if sub != "" || (a != "windows" && a != "range" && a != "rates" && a != "merge") {
255					return fail("unexpected argument %q", a)
256				}
257				sub = a
258				continue
259			}
260			name := a[1:]
261			if strings.HasPrefix(name, "-") {
262				name = name[1:]
263			}
264			value := ""
265			inline := false
266			if k := strings.IndexByte(name, '='); k >= 0 {
267				value = name[k+1:]
268				name = name[:k]
269				inline = true
270			}
271			switch name {
272			case "file", "window", "from", "to":
273				if !inline {
274					i++
275					if i >= len(args) {
276						return fail("flag --%s needs a value", name)
277					}
278					value = args[i]
279				}
280				if value == "" {
281					return fail("flag --%s needs a value", name)
282				}
283				switch name {
284				case "file":
285					cmd.files = append(cmd.files, value)
286				case "window":
287					cmd.window = value
288				case "from":
289					cmd.from, cmd.hasFrom = value, true
290				case "to":
291					cmd.to, cmd.hasTo = value, true
292				}
293			default:
294				return fail("unexpected argument %q", a)
295			}
296		}
297		cmd.sub = sub
298		if sub == "" {
299			return fail("expected a subcommand: windows, range, rates, or merge")
300		}
301		if len(cmd.files) == 0 {
302			return fail("--file is required")
303		}
304		switch sub {
305		case "merge":
306			if cmd.hasFrom || cmd.hasTo {
307				return fail("--from and --to belong to the range subcommand")
308			}
309			if len(cmd.files) != 2 {
310				return fail("merge takes exactly two --file arguments, got %d", len(cmd.files))
311			}
312		case "range", "rates":
313			if len(cmd.files) != 1 {
314				return fail("%s takes exactly one --file argument, got %d", sub, len(cmd.files))
315			}
316			if !cmd.hasFrom {
317				return fail("--from is required")
318			}
319			if !cmd.hasTo {
320				return fail("--to is required")
321			}
322		default: // windows
323			if cmd.hasFrom || cmd.hasTo {
324				return fail("--from and --to belong to the range subcommand")
325			}
326		}
327		if cmd.window == "" {
328			return fail("--window is required")
329		}
330		return cmd, true
331	}
332	
333	// ingester is the common ingestion surface of a Roller and a Counter:
334	// both file one validated sample at a time.
335	type ingester interface {
336		Add(at time.Time, value float64) error
337	}
338	
339	// ingestFile opens one input file and streams its samples into a fresh
340	// roller. It returns a non-zero exit code after writing one diagnostic if
341	// the file cannot be opened or its contents are invalid.
342	func ingestFile(path string, d time.Duration, stderr io.Writer) (*rollup.Roller, int) {
343		f, code := openInput(path, stderr)
344		if code != 0 {
345			return nil, code
346		}
347		defer f.Close()
348		roller := rollup.New(d)
349		if code := ingestInto(f, path, roller, stderr); code != 0 {
350			return nil, code
351		}
352		return roller, 0
353	}
354	
355	// ingestCounterFile opens one input file and streams its readings into a
356	// fresh counter, by the same file and content rules as ingestFile.
357	func ingestCounterFile(path string, d time.Duration, stderr io.Writer) (*rollup.Counter, int) {
358		f, code := openInput(path, stderr)
359		if code != 0 {
360			return nil, code
361		}
362		defer f.Close()
363		counter := rollup.NewCounter(d)
364		if code := ingestInto(f, path, counter, stderr); code != 0 {
365			return nil, code
366		}
367		return counter, 0
368	}
369	
370	// openInput opens one input file after confirming it exists and is not a
371	// directory. It returns exit code 3 after writing one diagnostic
372	// otherwise.
373	func openInput(path string, stderr io.Writer) (*os.File, int) {
374		info, err := os.Stat(path)
375		if err != nil {
376			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
377			return nil, 3
378		}
379		if info.IsDir() {
380			fmt.Fprintf(stderr, "rollupctl: %s: is a directory\n", path)
381			return nil, 3
382		}
383		f, err := os.Open(path)
384		if err != nil {
385			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
386			return nil, 3
387		}
388		return f, 0
389	}
390	
391	// ingestInto streams the records from in into dst. On any content problem
392	// it returns code 4 after writing one diagnostic naming the file and line;
393	// no output lines are printed by the caller in that case.
394	func ingestInto(in io.Reader, name string, dst ingester, stderr io.Writer) int {
395		contentError := func(line int, reason string) int {
396			fmt.Fprintf(stderr, "rollupctl: %s:%d: %s\n", name, line, reason)
397			return 4
398		}
399	
400		// The line buffer is capped at one byte over the limit, so a longer
401		// line fails immediately instead of growing with the file.
402		sc := bufio.NewScanner(in)
403		sc.Buffer(make([]byte, maxLineBytes+1), maxLineBytes+1)
404	
405		line := 0
406		samples := 0
407		for sc.Scan() {
408			line++
409			text := sc.Text()
410			if strings.TrimSpace(text) == "" {
411				continue
412			}
413			fields := strings.Fields(text)
414			if len(fields) != 2 {
415				return contentError(line, "expected a nanosecond timestamp and a value separated by whitespace")
416			}
417			ns, err := strconv.ParseInt(fields[0], 10, 64)
418			if err != nil {
419				return contentError(line, fmt.Sprintf("invalid timestamp %q", fields[0]))
420			}
421			value, err := strconv.ParseFloat(fields[1], 64)
422			if err != nil {
423				return contentError(line, fmt.Sprintf("invalid value %q", fields[1]))
424			}
425			if math.IsNaN(value) || math.IsInf(value, 0) {
426				return contentError(line, "value must be finite")
427			}
428			if err := dst.Add(time.Unix(0, ns).UTC(), value); err != nil {
429				return contentError(line, err.Error())
430			}
431			samples++
432		}
433		if err := sc.Err(); err != nil {
434			if errors.Is(err, bufio.ErrTooLong) {
435				// The over-long line is the one after every line already
436				// delivered, including an unterminated last line.
437				return contentError(line+1, "line is longer than 1024 bytes")
438			}
439			fmt.Fprintf(stderr, "rollupctl: %s: %v\n", name, err)
440			return 3
441		}
442		if samples == 0 {
443			return contentError(0, "no samples found")
444		}
445		return 0
446	}
447	
448	// formatFloat writes a float64 in its shortest round-trippable form; a
449	// negative zero keeps its sign and renders as -0.
450	func formatFloat(v float64) string {
451		return strconv.FormatFloat(v, 'g', -1, 64)
452	}
453	
454	var bigBillion = big.NewInt(1e9)
455	
456	// unixNanoText writes a window start as a signed integer count of
457	// nanoseconds since the epoch even when it falls outside the int64 range,
458	// so a start aligned past it is printed exactly instead of clamped.
459	func unixNanoText(t time.Time) string {
460		n := new(big.Int).Mul(big.NewInt(t.Unix()), bigBillion)
461		n.Add(n, big.NewInt(int64(t.Nanosecond())))
462		return n.String()
463	}
464

