// snapshot: samples filed after the call do not alter it. Series are
// reported in the order their labels first appeared, and the overflow
// bucket comes last; windows within each series are in time order.
func (s *SeriesSet) Snapshot() []SeriesWindow {
	s.mu.RLock()
	defer s.mu.RUnlock()

	out := make([]SeriesWindow, 0, len(s.order))
	for _, key := range s.order {
		e := s.series[key]
		labels := canonicalLabels(key, e)
		for _, w := range e.roller.Windows() {
			out = append(out, SeriesWindow{Labels: labels, Window: w})
		}
	}
	if s.bucket != nil {
		for _, w := range s.bucket.Windows() {
			out = append(out, SeriesWindow{Labels: map[string]string{}, Overflow: true, Window: w})
