	}
	return out
}

// canonicalLabels returns a fresh copy of the series' label map in a
// stable key order, or an allocated empty map for the empty-label series.
func canonicalLabels(key string, e *seriesEntry) map[string]string {
	// Labels are recovered from the key-independent map stored when the
	// series first claimed its slot; fall back to decoding if a caller
	// built the entry without one (the package's own paths always do).
	if e != nil && e.labels != nil {
		return cloneLabels(e.labels)
	}
	return decodeKey(key)
}

// cloneLabels returns a sorted, independently owned copy of labels.
func cloneLabels(labels map[string]string) map[string]string {
	out := make(map[string]string, len(labels))
	for k, v := range labels {
		out[k] = v
	}
	return out
}

// decodeKey reverses keyFor for report construction on entries assembled
// without a stored label map.
func decodeKey(key string) map[string]string {
	out := map[string]string{}
	for len(key) > 0 {
		n, rest, ok := takePrefix(key, ':')
		if !ok {
			return out
		}
		_ = n
		key = rest
	}
	return out
}

// takePrefix is a small helper used by decodeKey.
func takePrefix(s string, sep byte) (string, string, bool) {
	for i := 0; i < len(s); i++ {
		if s[i] == sep {
			return s[:i], s[i+1:], true
		}
	}
	return s, "", false
}

// Cardinality returns a snapshot of the quota accounting: the number of
// slot-occupying series, the number of distinct series that have spilled
// into the overflow bucket, and the number of samples refused under
// OverflowReject.
func (s *SeriesSet) Cardinality() CardinalityReport {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return CardinalityReport{
		AcceptedSeries:  len(s.order),
		OverflowSeries:  len(s.overflow),
		RejectedSamples: s.rejected,
	}
}

