func TestSeriesSetConcurrent(t *testing.T) {
	s := NewSeriesSet(time.Second, SeriesConfig{MaxSeries: 8, Overflow: OverflowAggregate})
	var wg sync.WaitGroup
	stop := make(chan struct{})
	for w := 0; w < 4; w++ {
		wg.Add(1)
		go func(worker int) {
			defer wg.Done()
			i := 0
			for {
				select {
				case <-stop:
					return
				default:
				}
				labels := map[string]string{"h": fmt.Sprintf("g%d", (worker+i)%12)}
				// Non-decreasing timestamps per worker are not guaranteed
				// across label identity; OOO errors are expected and must
				// leave the set usable.
				_ = s.Add(ls(int64(i%50), float64(i), labels))
				i++
				if i > 400 {
					return
				}
			}
		}(w)
	}
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-stop:
				return
			default:
			}
			_ = s.Snapshot()
			_ = s.Cardinality()
		}
	}()
	wg.Wait()
	close(stop)
	// Quota invariants always hold.
	card := s.Cardinality()
	if card.AcceptedSeries > 8 {
		t.Fatalf("accepted %d series, quota 8", card.AcceptedSeries)
	}
	if card.OverflowSeries > 4 { // 12 label identities - 8 slots
		t.Fatalf("overflow series = %d, want at most 4", card.OverflowSeries)
	}
	for _, sw := range s.Snapshot() {
		if strings.Contains(sw.Labels["h"], "MUTATED") {
			t.Fatal("label map corrupted")
		}
	}
}

