func TestSeriesLabelObjectAllowsInnerWhitespace(t *testing.T) {
	content := "0 1 { \"host\" : \"a\" , \"zone\": \"z1\" }\n"
	got := runSeriesWithFile(t, content, "--window", "1s", "--max-series", "1", "--overflow", "aggregate")
